DROP POLICY private_media_add ON storage.objects;
CREATE POLICY private_media_add ON storage.objects FOR INSERT TO authenticated WITH CHECK(public.is_couple_member() AND bucket_id IN ('photos','videos','thumbnails'));
CREATE POLICY private_media_update ON storage.objects FOR UPDATE TO authenticated USING(public.is_couple_member() AND bucket_id IN ('photos','videos','thumbnails')) WITH CHECK(public.is_couple_member() AND ((bucket_id IN ('photos','thumbnails') AND metadata->>'mimetype' IN ('image/jpeg','image/png','image/webp','image/gif') AND (metadata->>'size')::bigint<=20971520) OR (bucket_id='videos' AND metadata->>'mimetype' IN ('video/mp4','video/webm','video/quicktime') AND (metadata->>'size')::bigint<=104857600)));
CREATE FUNCTION public.validate_private_upload() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.bucket_id IN ('photos','videos','thumbnails') AND NEW.metadata IS NOT NULL AND NEW.metadata ? 'mimetype' THEN IF NEW.bucket_id IN ('photos','thumbnails') AND (NEW.metadata->>'mimetype' NOT IN ('image/jpeg','image/png','image/webp','image/gif') OR (NEW.metadata->>'size')::bigint>20971520) THEN RAISE EXCEPTION 'Photos must be an accepted image type and 20 MB or smaller.'; END IF; IF NEW.bucket_id='videos' AND (NEW.metadata->>'mimetype' NOT IN ('video/mp4','video/webm','video/quicktime') OR (NEW.metadata->>'size')::bigint>104857600) THEN RAISE EXCEPTION 'Videos must be MP4, WebM or MOV and 100 MB or smaller.'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_private_upload BEFORE INSERT OR UPDATE ON storage.objects FOR EACH ROW EXECUTE FUNCTION public.validate_private_upload();